// The agent (spec 0004 T7, ADR 0046): one system prompt, one bounded
// tool-calling loop, and a dispatcher that executes a tool call by
// name. The model chooses *what* to call; this node decides *as whom*
// (ADR 0042 -- the shape declared in tools/<name>.json, never anything
// the model said); the database decides *whether*.
const crypto = require('crypto');
const http = require('http');
const https = require('https');
const fs = require('fs');
const { URL } = require('url');

const PG = 'http://postgrest:3000';
const TOOLS_DIR = '/tools';
const PROMPT_PATH = '/prompts/agent/v1/system.md';
const PROMPT_VERSION = 'agent@1';
// A model that calls tools badly loops. This cap is the thing that
// stops it, so it is load-bearing rather than defensive (ADR 0046).
const MAX_ROUNDS = 8;
const HISTORY_LIMIT = 12;

function b64url(buf) {
  return buf.toString('base64').replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}

function mintToken(role, memberId) {
  const header = b64url(Buffer.from(JSON.stringify({ alg: 'HS256', typ: 'JWT' })));
  const payload = b64url(Buffer.from(JSON.stringify({ role, member_id: memberId, exp: Math.floor(Date.now() / 1000) + 120 })));
  const signingInput = `${header}.${payload}`;
  const signature = b64url(crypto.createHmac('sha256', $env.PGRST_JWT_SECRET).update(signingInput).digest());
  return `${signingInput}.${signature}`;
}

function httpJson(method, url, headers, body) {
  return new Promise((resolve, reject) => {
    const bodyStr = body !== undefined ? JSON.stringify(body) : undefined;
    const u = new URL(url);
    const options = {
      hostname: u.hostname, port: u.port, path: u.pathname + u.search, method,
      headers: Object.assign({ 'Content-Type': 'application/json' }, headers, bodyStr ? { 'Content-Length': Buffer.byteLength(bodyStr) } : {}),
    };
    const req = http.request(options, (res) => {
      let data = '';
      res.on('data', (c) => (data += c));
      res.on('end', () => {
        let parsed = null;
        try { parsed = data ? JSON.parse(data) : null; } catch (e) { parsed = data; }
        resolve({ status: res.statusCode, body: parsed });
      });
    });
    req.on('error', reject);
    if (bodyStr) req.write(bodyStr);
    req.end();
  });
}

// Telling the admins about a correction request (R16a) is a side
// effect of the tool, not a decision -- so it lives here rather than
// being something the agent has to remember to do.
function telegramSend(botToken, chatId, text) {
  return new Promise((resolve) => {
    const bodyStr = JSON.stringify({ chat_id: chatId, text });
    const req = https.request({
      hostname: 'api.telegram.org', path: `/bot${botToken}/sendMessage`, method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(bodyStr) },
    }, (res) => { res.on('data', () => {}); res.on('end', () => resolve()); });
    req.on('error', () => resolve());
    req.write(bodyStr);
    req.end();
  });
}

// R21: an export is delivered in the chat it was asked for, as a
// file rather than a wall of text. Best-effort, like the admin
// notification above: a delivery that fails must not lose the reply
// that says what was exported.
function telegramSendDocument(botToken, chatId, filename, content) {
  return new Promise((resolve) => {
    const boundary = `----meowhub${Date.now()}`;
    const head = `--${boundary}\r\nContent-Disposition: form-data; name="chat_id"\r\n\r\n${chatId}\r\n`
      + `--${boundary}\r\nContent-Disposition: form-data; name="document"; filename="${filename}"\r\n`
      + 'Content-Type: text/csv\r\n\r\n';
    const tail = `\r\n--${boundary}--\r\n`;
    const body = Buffer.concat([Buffer.from(head), Buffer.from(content), Buffer.from(tail)]);
    const req = https.request({
      hostname: 'api.telegram.org', path: `/bot${botToken}/sendDocument`, method: 'POST',
      headers: { 'Content-Type': `multipart/form-data; boundary=${boundary}`, 'Content-Length': body.length },
    }, (res) => { res.on('data', () => {}); res.on('end', () => resolve()); });
    req.on('error', () => resolve());
    req.write(body);
    req.end();
  });
}

// --- the tool registry: declarations are the authority -------------
// A tool the dispatcher cannot execute is never offered to the model,
// so there is one list rather than two that can drift.
function loadDeclarations() {
  const out = {};
  for (const file of fs.readdirSync(TOOLS_DIR)) {
    if (!file.endsWith('.json')) continue;
    try {
      const d = JSON.parse(fs.readFileSync(`${TOOLS_DIR}/${file}`, 'utf8'));
      if (d && d.name) out[d.name] = d;
    } catch (e) { /* a malformed declaration is not a tool */ }
  }
  return out;
}

const q = (v) => encodeURIComponent(String(v));

// name -> (params, ctx) => { method, path, body? }. Read tools return
// view rows verbatim; nothing here reformats a figure, because a
// figure this node touched is one the database no longer vouches for.
const DISPATCH = {
  spend_total: (p) => ({ method: 'GET', path: `/v_period_spend?period=eq.${q(p.period || 'this_month')}` }),
  spend_by_category: (p) => ({
    method: 'GET',
    path: `/v_category_spend?period=eq.${q(p.period || 'this_month')}`
      + (p.category_slug ? `&category_slug=eq.${q(p.category_slug)}` : '')
      + '&order=amount_minor.desc&amount_minor=gt.0',
  }),
  spend_by_category_trend: (p) => ({ method: 'GET', path: `/v_category_spend_by_month?category_slug=eq.${q(p.category_slug)}&order=month.asc` }),
  spend_by_merchant: (p) => ({
    method: 'GET',
    path: `/v_merchant_spend?period=eq.${q(p.period || 'this_month')}`
      + (p.merchant_name ? `&merchant_name=ilike.*${q(p.merchant_name)}*` : '')
      + '&order=amount_minor.desc&amount_minor=gt.0',
  }),
  spend_by_merchant_trend: (p) => ({ method: 'GET', path: `/v_merchant_spend_by_month?merchant_name=ilike.*${q(p.merchant_name)}*&order=month.asc` }),
  spend_by_member: (p, ctx) => ({
    method: 'GET',
    path: `/v_member_spend?period=eq.${q(p.period || 'this_month')}`
      + (p.member_scope === 'self' ? `&member_id=eq.${ctx.member_id}` : '')
      + '&order=amount_minor.desc',
  }),
  spend_by_member_trend: (p, ctx) => ({ method: 'GET', path: `/v_member_spend_by_month?member_id=eq.${p.member_id || ctx.member_id}&order=month.asc` }),
  account_balance: (p) => ({ method: 'GET', path: `/v_account_balance?name=ilike.*${q(p.account_name)}*` }),
  household_position: () => ({ method: 'GET', path: '/v_household_position' }),
  liability_summary: () => ({ method: 'GET', path: '/v_liability_summary' }),
  unconfirmed_summary: () => ({ method: 'GET', path: '/v_unconfirmed_summary' }),
  list_unconfirmed: (p) => ({ method: 'GET', path: `/v_unconfirmed?order=created_at.desc&limit=${Number(p.limit) || 20}` }),
  list_recent_captures: (p, ctx) => ({ method: 'GET', path: `/v_transaction_detail?submitter=eq.${ctx.member_id}&order=id.desc&limit=${Number(p.limit) || 5}` }),
  search_transactions: (p) => ({ method: 'GET', path: `/v_transaction_search?searchable_text=ilike.*${q(p.query)}*&order=date.desc&limit=20` }),
  why_category: (p) => ({ method: 'GET', path: `/v_transaction_detail?id=eq.${Number(p.transaction_id)}` }),
  // R15: a member's own digests, and nothing else about them -- the
  // column grant is what makes this a member's call rather than an
  // admin's.
  set_digest_preference: (p, ctx) => ({
    method: 'PATCH', path: `/member?id=eq.${ctx.member_id}`,
    body: Object.assign({},
      p.weekly === undefined ? {} : { digest_weekly: p.weekly },
      p.monthly === undefined ? {} : { digest_monthly: p.monthly }),
  }),
  find_merchant: (p) => ({ method: 'GET', path: `/v_merchant_lookup?match_text=ilike.*${q(p.text)}*` }),
  find_category: (p) => ({ method: 'GET', path: `/v_category${p.text ? `?or=(slug.ilike.*${q(p.text)}*,display_name.ilike.*${q(p.text)}*)` : '?limit=100'}` }),
  find_account: (p) => ({
    method: 'GET',
    path: `/v_account_balance?${p.text ? `name=ilike.*${q(p.text)}*` : 'limit=50'}` + (p.type ? `&type=eq.${q(p.type)}` : ''),
  }),
  create_merchant: (p) => ({ method: 'POST', path: '/merchant', body: { name: p.name } }),
  create_category: (p) => ({
    method: 'POST', path: '/account',
    body: { type: 'expense', name: p.slug, reviewed: false },
  }),
  find_recent_transaction: (p, ctx) => ({
    method: 'GET',
    path: `/v_transaction_detail?order=id.desc&limit=${Number(p.limit) || 5}`
      + (p.mine_only ? `&submitter=eq.${ctx.member_id}` : '')
      + (p.unconfirmed_only ? '&confirmation_state=eq.unconfirmed' : ''),
  }),
  transaction_lines: (p) => ({ method: 'GET', path: `/v_account_movement?transaction_id=eq.${Number(p.transaction_id)}` }),
  confirm_transaction: (p, ctx) => ({
    method: 'PATCH', path: `/transaction?id=eq.${Number(p.transaction_id)}`,
    body: {
      confirmation_state: 'confirmed', confirmation_route: 'review',
      confirmed_by: ctx.member_id, confirmed_at: new Date().toISOString(),
    },
  }),
  delete_transaction: (p) => ({ method: 'DELETE', path: `/transaction?id=eq.${Number(p.transaction_id)}` }),
  open_account: (p) => ({
    method: 'POST', path: '/account',
    body: { type: p.type, name: p.name, currency: p.currency || undefined, parent_id: p.parent_id || undefined },
  }),
  set_default_payment_account: (p, ctx) => ({
    method: 'PATCH', path: `/member?id=eq.${ctx.member_id}`,
    body: { default_payment_account_id: Number(p.account_id) },
  }),
  remember: (p, ctx) => ({
    method: 'POST', path: '/agent_memory',
    body: { member_id: p.member_id === undefined ? ctx.member_id : p.member_id, content: p.content },
  }),
};

// Movement and largest expenses need the period's own bounds, which
// come from SQL (ADR 0045) -- this node never computes a date.
async function periodBounds(period, auth) {
  const res = await httpJson('GET', `${PG}/v_reporting_period?period=eq.${q(period || 'this_month')}`, auth);
  return (res.body || [])[0] || null;
}

async function executeTool(name, params, ctx) {
  const decl = ctx.declarations[name];
  if (!decl) return { error: `no such tool: ${name}` };

  // ADR 0042: the declaration's shape decides the acting identity.
  // "composes" is the agent's own act on a member's behalf; anything
  // else runs as the member themselves, so a tool they may not use is
  // refused by the database rather than by this node.
  const role = decl.shape === 'composes' ? 'hh_agent' : (ctx.is_admin ? 'hh_admin' : 'hh_member');
  const auth = { Authorization: `Bearer ${mintToken(role, ctx.member_id)}` };

  // R13: a transaction and its postings are one act, and no member may
  // write a raw posting under any role -- so this composes as hh_agent
  // whoever asked for it, exactly as spec 0003's own capture did.
  if (name === 'record_transaction') {
    const txnRes = await httpJson('POST', `${PG}/transaction`, Object.assign({ Prefer: 'return=representation' }, auth), {
      date: params.date, submitter: params.member_id || ctx.member_id, source: params.source || 'text',
      merchant_id: params.merchant_id || null, category_source: params.category_source || 'model',
      model: params.model || null, prompt_version: params.prompt_version || null,
      original_amount: params.original_amount_minor || null, original_currency: params.original_currency || null,
      note: params.note || null, inferred_fields: params.inferred_fields || [],
    });
    if (txnRes.status < 200 || txnRes.status >= 300) {
      return { error: (txnRes.body && txnRes.body.message) || `refused with status ${txnRes.status}`, status: txnRes.status };
    }
    const transactionId = txnRes.body[0].id;
    const currency = params.currency || 'EUR';
    const postings = await httpJson('POST', `${PG}/posting`, Object.assign({ Prefer: 'return=minimal' }, auth), [
      { transaction_id: transactionId, account_id: params.account_id, amount: -params.amount_minor, currency },
      { transaction_id: transactionId, account_id: params.category_account_id, amount: params.amount_minor, currency },
    ]);
    if (postings.status < 200 || postings.status >= 300) {
      return { error: (postings.body && postings.body.message) || `postings refused with status ${postings.status}`, status: postings.status };
    }
    return { transaction_id: transactionId, rows: txnRes.body };
  }

  // R21: the books, removable from the household at any time. One row
  // per posting for the period, RFC 4180: fields carrying a comma, a
  // quote or a newline are quoted and their quotes doubled, records
  // end CRLF. The period's bounds come from SQL (ADR 0045).
  if (name === 'export_period') {
    const bounds = await periodBounds(params.period, auth);
    if (!bounds) return { error: `not a period this household can be asked about: ${params.period}` };
    const rows = await httpJson(
      'GET',
      `${PG}/v_account_movement?date=gte.${bounds.period_start}&date=lte.${bounds.period_end}&order=date.asc,transaction_id.asc`,
      auth
    );
    if (rows.status < 200 || rows.status >= 300) {
      return { error: (rows.body && rows.body.message) || `refused with status ${rows.status}`, status: rows.status };
    }
    const columns = ['date', 'transaction_id', 'account_name', 'account_type', 'amount_minor', 'currency', 'merchant_name', 'note', 'confirmation_state'];
    const field = (v) => {
      if (v === null || v === undefined) return '';
      const s = String(v);
      return /[",\r\n]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s;
    };
    const lines = [columns.join(',')];
    let expenseTotal = 0;
    for (const row of rows.body || []) {
      if (row.account_type === 'expense') expenseTotal += Number(row.amount_minor) || 0;
      lines.push(columns.map((col) => field(row[col])).join(','));
    }
    return {
      csv: lines.join('\r\n') + '\r\n',
      filename: `meowhub-${params.period.replace(/[^A-Za-z0-9_-]/g, '-')}.csv`,
      period: bounds,
      posting_count: (rows.body || []).length,
      expense_total_minor: expenseTotal,
    };
  }

  // R0c: renaming, deactivating or re-terming an account. A new term
  // is a new account_term row, never an edit -- the table is
  // append-only, so a rate change keeps its own history (spec 0003 T1).
  if (name === 'amend_account') {
    const fields = {};
    for (const key of ['name', 'active', 'reviewed']) {
      if (params[key] !== undefined && params[key] !== null) fields[key] = params[key];
    }
    if (Object.keys(fields).length) {
      const res = await httpJson('PATCH', `${PG}/account?id=eq.${Number(params.account_id)}`, Object.assign({ Prefer: 'return=minimal' }, auth), fields);
      if (res.status < 200 || res.status >= 300) return { error: (res.body && res.body.message) || `refused with status ${res.status}`, status: res.status };
    }
    const term = {};
    for (const key of ['overdraft_limit', 'credit_limit', 'interest_rate', 'payment_amount', 'payment_day']) {
      if (params[key] !== undefined && params[key] !== null) term[key] = params[key];
    }
    if (Object.keys(term).length) {
      term.account_id = Number(params.account_id);
      term.effective_from = new Date().toISOString().slice(0, 10);
      const res = await httpJson('POST', `${PG}/account_term`, Object.assign({ Prefer: 'return=minimal' }, auth), term);
      if (res.status < 200 || res.status >= 300) return { error: (res.body && res.body.message) || `refused with status ${res.status}`, status: res.status };
    }
    return { amended: Number(params.account_id) };
  }

  // R0d: the household's own settings. Written as JSON, so a number
  // stays a number -- period_bounds and the auto-confirm guard both
  // read these back as bigints.
  if (name === 'set_household_setting') {
    const raw = params.value;
    const value = /^-?\d+(\.\d+)?$/.test(String(raw)) ? Number(raw) : String(raw);
    const existing = await httpJson('GET', `${PG}/household_setting?key=eq.${q(params.key)}&select=id`, auth);
    const found = (existing.body || [])[0];
    const res = found
      ? await httpJson('PATCH', `${PG}/household_setting?id=eq.${found.id}`, Object.assign({ Prefer: 'return=minimal' }, auth), { value, updated_by: ctx.member_id })
      : await httpJson('POST', `${PG}/household_setting`, Object.assign({ Prefer: 'return=minimal' }, auth), { key: params.key, value, updated_by: ctx.member_id });
    if (res.status < 200 || res.status >= 300) return { error: (res.body && res.body.message) || `refused with status ${res.status}`, status: res.status };
    return { setting: params.key };
  }

  // R0c: merging one category into another -- every posting repointed,
  // the merged-away one deactivated. Admin-only at the database.
  if (name === 'merge_category') {
    const repointed = await httpJson('PATCH', `${PG}/posting?account_id=eq.${Number(params.from_account_id)}`, Object.assign({ Prefer: 'return=minimal' }, auth), { account_id: Number(params.into_account_id) });
    if (repointed.status < 200 || repointed.status >= 300) return { error: (repointed.body && repointed.body.message) || `refused with status ${repointed.status}`, status: repointed.status };
    const deactivated = await httpJson('PATCH', `${PG}/account?id=eq.${Number(params.from_account_id)}`, Object.assign({ Prefer: 'return=minimal' }, auth), { active: false });
    if (deactivated.status < 200 || deactivated.status >= 300) return { error: (deactivated.body && deactivated.body.message) || `refused with status ${deactivated.status}`, status: deactivated.status };
    return { merged: Number(params.from_account_id), into: Number(params.into_account_id) };
  }

  // R15a: reclassification is never a financial fact, so it is a plain
  // update to the expense side of the transaction -- and the project
  // is the same kind of change on the transaction itself.
  if (name === 'classify_transaction') {
    if (params.category_account_id) {
      const lines = await httpJson('GET', `${PG}/posting?transaction_id=eq.${Number(params.transaction_id)}&amount=gt.0&select=id`, auth);
      const expenseLine = (lines.body || [])[0];
      if (!expenseLine) return { error: 'that transaction has no expense side to reclassify' };
      const res = await httpJson('PATCH', `${PG}/posting?id=eq.${expenseLine.id}`, Object.assign({ Prefer: 'return=minimal' }, auth), { account_id: params.category_account_id });
      if (res.status < 200 || res.status >= 300) return { error: (res.body && res.body.message) || `refused with status ${res.status}`, status: res.status };
    }
    if (params.project_id !== undefined && params.project_id !== null) {
      const res = await httpJson('PATCH', `${PG}/transaction?id=eq.${Number(params.transaction_id)}`, Object.assign({ Prefer: 'return=minimal' }, auth), { project_id: params.project_id });
      if (res.status < 200 || res.status >= 300) return { error: (res.body && res.body.message) || `refused with status ${res.status}`, status: res.status };
    }
    return { reclassified: Number(params.transaction_id) };
  }

  // A correction to an amount touches both legs in one commit --
  // posting_balance_check is deferred, so two PATCHes would fail at the
  // first one's own commit (spec 0003 T11).
  if (name === 'correct_transaction') {
    if (params.amount_minor !== undefined && params.amount_minor !== null) {
      const res = await httpJson('POST', `${PG}/rpc/correct_posting_amounts`, auth, {
        p_transaction_id: Number(params.transaction_id), p_new_amount_minor: Number(params.amount_minor),
      });
      if (res.status < 200 || res.status >= 300) return { error: (res.body && res.body.message) || `refused with status ${res.status}`, status: res.status };
    }
    const fields = {};
    if (params.date) fields.date = params.date;
    if (params.merchant_id !== undefined && params.merchant_id !== null) fields.merchant_id = params.merchant_id;
    if (Object.keys(fields).length) {
      const res = await httpJson('PATCH', `${PG}/transaction?id=eq.${Number(params.transaction_id)}`, Object.assign({ Prefer: 'return=minimal' }, auth), fields);
      if (res.status < 200 || res.status >= 300) return { error: (res.body && res.body.message) || `refused with status ${res.status}`, status: res.status };
    }
    if (params.account_id !== undefined && params.account_id !== null) {
      const lines = await httpJson('GET', `${PG}/posting?transaction_id=eq.${Number(params.transaction_id)}&amount=lt.0&select=id`, auth);
      const paymentLine = (lines.body || [])[0];
      if (paymentLine) {
        const res = await httpJson('PATCH', `${PG}/posting?id=eq.${paymentLine.id}`, Object.assign({ Prefer: 'return=minimal' }, auth), { account_id: params.account_id });
        if (res.status < 200 || res.status >= 300) return { error: (res.body && res.body.message) || `refused with status ${res.status}`, status: res.status };
      }
    }
    return { corrected: Number(params.transaction_id) };
  }

  // R16a: a change the member may not make themselves becomes a
  // request, and the admins are told. The row is the member's own
  // (tools/request_correction.json declares it acts_as/hh_member).
  if (name === 'request_correction') {
    const res = await httpJson('POST', `${PG}/correction_request`, Object.assign({ Prefer: 'return=minimal' }, auth), {
      transaction_id: Number(params.transaction_id), requested_by: ctx.member_id,
      requested_change: params.requested_change || {}, status: 'open',
    });
    if (res.status < 200 || res.status >= 300) return { error: (res.body && res.body.message) || `refused with status ${res.status}`, status: res.status };
    const admins = await httpJson('GET', `${PG}/member?role=eq.admin&select=id`, { Authorization: `Bearer ${mintToken('hh_agent', ctx.member_id)}` });
    const botToken = $env.TELEGRAM_DELIVERY_MODE === 'polling' ? $env.TELEGRAM_LOCAL_BOT_TOKEN : $env.TELEGRAM_BOT_TOKEN;
    for (const admin of admins.body || []) {
      const channels = await httpJson('GET', `${PG}/member_channel?member_id=eq.${admin.id}&kind=eq.telegram&select=external_id`, { Authorization: `Bearer ${mintToken('hh_agent', ctx.member_id)}` });
      for (const channel of channels.body || []) {
        if (botToken) await telegramSend(botToken, channel.external_id, `Correction requested for transaction #${params.transaction_id}: ${JSON.stringify(params.requested_change || {})}`);
      }
    }
    return { requested: Number(params.transaction_id), admins_notified: (admins.body || []).length };
  }

  // ADR 0036: undo is the actor's own most recent action, reversed as a
  // new compensating change. Nothing already written is touched.
  if (name === 'undo_last_action') {
    const auditRes = await httpJson(
      'GET',
      `${PG}/audit_log?actor=eq.${ctx.member_id}&table_name=in.(transaction,posting)&order=id.desc&limit=10&select=id,table_name,row_id,operation,before_state`,
      { Authorization: `Bearer ${mintToken('hh_agent', ctx.member_id)}` }
    );
    // A posting insert is a mechanical side effect of the transaction
    // beside it, never an action of its own.
    const last = (auditRes.body || []).find(
      (a) => (a.table_name === 'transaction' && a.operation === 'insert') || (a.table_name === 'posting' && a.operation === 'update')
    );
    if (!last) return { error: 'nothing of yours to undo' };

    if (last.operation === 'insert') {
      const composeAuth = { Authorization: `Bearer ${mintToken('hh_agent', ctx.member_id)}` };
      const lines = await httpJson('GET', `${PG}/posting?transaction_id=eq.${last.row_id}&select=account_id,amount,currency`, composeAuth);
      const postings = lines.body || [];
      if (!postings.length) return { error: 'already undone' };
      const reversal = await httpJson('POST', `${PG}/transaction`, Object.assign({ Prefer: 'return=representation' }, composeAuth), {
        date: new Date().toISOString().slice(0, 10), submitter: ctx.member_id, source: 'manual',
        note: `undo of #${last.row_id}`, inferred_fields: [],
        confirmation_state: 'confirmed', confirmation_route: 'review',
        confirmed_by: ctx.member_id, confirmed_at: new Date().toISOString(),
      });
      if (reversal.status < 200 || reversal.status >= 300) return { error: (reversal.body && reversal.body.message) || 'could not record the reversal' };
      const reversalId = reversal.body[0].id;
      await httpJson('POST', `${PG}/posting`, Object.assign({ Prefer: 'return=minimal' }, composeAuth),
        postings.map((p) => ({ transaction_id: reversalId, account_id: p.account_id, amount: -p.amount, currency: p.currency })));
      return { undone: Number(last.row_id), reversal_transaction_id: reversalId };
    }

    const restored = await httpJson('PATCH', `${PG}/posting?id=eq.${last.row_id}`, Object.assign({ Prefer: 'return=minimal' }, auth), {
      account_id: last.before_state && last.before_state.account_id,
    });
    if (restored.status < 200 || restored.status >= 300) return { error: 'that cannot be undone here' };
    return { undone: Number(last.row_id) };
  }

  let call;
  if (name === 'account_movement' || name === 'largest_expenses') {
    const bounds = await periodBounds(params.period, auth);
    if (!bounds) return { error: `not a period this household can be asked about: ${params.period}` };
    const window = `date=gte.${bounds.period_start}&date=lte.${bounds.period_end}`;
    call = name === 'account_movement'
      ? { method: 'GET', path: `/v_account_movement?account_name=ilike.*${q(params.account_name)}*&${window}&order=date.desc&limit=50` }
      : { method: 'GET', path: `/v_account_movement?account_type=eq.expense&${window}&order=amount_minor.desc&limit=${Number(params.limit) || 5}` };
    call.period = bounds;
  } else {
    const build = DISPATCH[name];
    if (!build) return { error: `tool declared but not wired: ${name}` };
    call = build(params, ctx);
  }

  const headers = call.method === 'GET' ? auth : Object.assign({ Prefer: 'return=representation' }, auth);
  const res = await httpJson(call.method, `${PG}${call.path}`, headers, call.body);

  if (res.status < 200 || res.status >= 300) {
    // A refusal is a result the agent can act on, not a crash: it may
    // tell the member it is not allowed, or try something else.
    return { error: (res.body && res.body.message) || `refused with status ${res.status}`, status: res.status };
  }

  // create_merchant's alias and default category are second writes,
  // kept here rather than asked of the model twice.
  if (name === 'create_merchant' && Array.isArray(res.body) && res.body[0]) {
    const merchantId = res.body[0].id;
    if (params.alias) {
      await httpJson('POST', `${PG}/merchant_alias`, Object.assign({ Prefer: 'return=minimal' }, auth), { merchant_id: merchantId, alias: params.alias });
    }
    if (params.default_category_slug) {
      const cat = await httpJson('GET', `${PG}/account?type=eq.expense&name=eq.${q(params.default_category_slug)}&select=id`, auth);
      if ((cat.body || []).length) {
        await httpJson('PATCH', `${PG}/merchant?id=eq.${merchantId}`, Object.assign({ Prefer: 'return=minimal' }, auth), { default_category_id: cat.body[0].id });
      }
    }
  }
  if (name === 'create_category' && Array.isArray(res.body) && res.body[0]) {
    await httpJson('POST', `${PG}/translation`, Object.assign({ Prefer: 'return=minimal' }, auth), [
      { slug: params.slug, language: 'en', display_name: params.display_name_en },
      { slug: params.slug, language: 'ru', display_name: params.display_name_ru },
    ]);
  }

  return { rows: res.body, period: call.period };
}

async function main() {
  const item = $input.first().json;
  const { member_id, chat_id, message_thread_id, text, language_hint, channel_message_id } = item;
  const isRu = language_hint === 'ru';

  const readAuth = { Authorization: `Bearer ${mintToken('hh_agent', member_id)}` };

  const [memberRes, settingsRes, historyRes, memoryRes, openConvRes] = await Promise.all([
    httpJson('GET', `${PG}/member?id=eq.${member_id}&select=id,role,language,default_payment_account_id`, readAuth),
    httpJson('GET', `${PG}/household_setting?select=key,value`, readAuth),
    // ADR 0043: the whole recent exchange in this chat is context,
    // across members, not only this member's own messages.
    httpJson('GET', `${PG}/capture?chat_id=eq.${q(chat_id)}&order=id.desc&limit=${HISTORY_LIMIT}&select=direction,raw_text,member_id`, readAuth),
    httpJson('GET', `${PG}/agent_memory?or=(member_id.eq.${member_id},member_id.is.null)&select=content`, readAuth),
    // ADR 0038: a clarifying exchange in progress is a row, not state
    // held in this workflow between messages.
    httpJson('GET', `${PG}/conversation?member_id=eq.${member_id}&kind=eq.clarification&closed_at=is.null`, readAuth),
  ]);

  let conversation = (openConvRes.body || [])[0] || null;
  let convHistory = [];
  if (conversation) {
    const convRes = await httpJson('GET', `${PG}/capture?conversation_id=eq.${conversation.id}&order=sequence.asc&select=direction,raw_text,sequence`, readAuth);
    convHistory = convRes.body || [];
  }
  // R17/A41: what has already been asked in *this* exchange, so the
  // agent never repeats a question it has had no new information since.
  const questionsAsked = convHistory.filter((h) => h.direction === 'outbound').map((h) => h.raw_text);
  const nextSequence = convHistory.reduce((max, h) => Math.max(max, h.sequence || 0), 0) + 1;

  const member = (memberRes.body || [])[0] || {};
  const isAdmin = member.role === 'admin';
  const settings = {};
  (settingsRes.body || []).forEach((s) => { settings[s.key] = s.value; });

  const declarations = loadDeclarations();
  const wired = Object.keys(declarations).filter((n) => DISPATCH[n] || n === 'account_movement' || n === 'largest_expenses');
  const tools = wired.map((n) => ({
    type: 'function',
    function: { name: n, description: declarations[n].purpose, parameters: declarations[n].input_schema },
  }));

  const history = (historyRes.body || []).slice().reverse();
  const memory = (memoryRes.body || []).map((m) => m.content);

  let defaultAccountName = null;
  if (member.default_payment_account_id) {
    const accRes = await httpJson('GET', `${PG}/account?id=eq.${member.default_payment_account_id}&select=name`, readAuth);
    defaultAccountName = (accRes.body || [])[0] ? accRes.body[0].name : null;
  }

  const context = {
    member_id, is_admin: isAdmin,
    default_payment_account: defaultAccountName,
    questions_already_asked: questionsAsked,
    language: member.language || language_hint || 'en',
    timezone: settings.timezone || 'UTC',
    // Whether the household has actually said, as against this
    // falling back to UTC -- which is what "still to set up" means.
    timezone_set: Boolean(settings.timezone),
    currency: settings.default_currency || 'EUR',
    today: new Date().toLocaleDateString('en-CA', { timeZone: settings.timezone || 'UTC' }),
    memory,
  };

  const systemPrompt = fs.readFileSync(PROMPT_PATH, 'utf8');
  const messages = [
    { role: 'system', content: systemPrompt },
    { role: 'system', content: `Context for this exchange: ${JSON.stringify(context)}` },
  ];
  for (const h of history) {
    messages.push({ role: h.direction === 'outbound' ? 'assistant' : 'user', content: h.raw_text || '' });
  }
  messages.push({ role: 'user', content: text });

  const modelName = $env.MODEL_AGENT || 'meowhub/agent-stub';
  const ctx = { member_id, is_admin: isAdmin, declarations, language: context.language };

  async function storeCapture(fields) {
    return httpJson('POST', `${PG}/capture`, Object.assign({ Prefer: 'return=representation' }, readAuth), Object.assign({
      member_id, chat_id: String(chat_id), kind: 'text',
      channel_message_id: channel_message_id ? String(channel_message_id) : null,
    }, fields));
  }

  // R6a: the message that reached us is stored before anything is
  // attempted, so nothing is ever lost to a failure below.
  const inboundRes = await storeCapture({
    direction: 'inbound', sequence: nextSequence, raw_text: text, state: 'unparsed',
    conversation_id: conversation ? conversation.id : null,
  });
  const inboundId = (inboundRes.body || [])[0] ? inboundRes.body[0].id : null;

  const fallback = isRu
    ? 'Не получилось обработать это сейчас — ничего не потеряно, разберёмся позже.'
    : "Couldn't handle that just now -- nothing is lost, it will be dealt with.";

  let reply = null;
  const toolResults = [];

  for (let round = 0; round < MAX_ROUNDS; round++) {
    let modelRes;
    try {
      modelRes = await httpJson('POST', `${$env.OPENROUTER_BASE_URL}/chat/completions`, {}, { model: modelName, messages, tools });
      if (!modelRes || modelRes.status < 200 || modelRes.status >= 300) throw new Error(`gateway status ${modelRes && modelRes.status}`);
    } catch (e) {
      // A13/A20: the gateway is unreachable. Say something true, keep
      // the message, invent nothing.
      await storeCapture({ direction: 'outbound', sequence: nextSequence + 1, raw_text: fallback, conversation_id: conversation ? conversation.id : null });
      return [{ json: { chat_id, message_thread_id, text: fallback } }];
    }

    const choice = (modelRes.body && modelRes.body.choices && modelRes.body.choices[0]) || {};
    const message = choice.message || {};

    if (message.tool_calls && message.tool_calls.length) {
      messages.push(message);
      for (const call of message.tool_calls) {
        const fn = (call.function || {});
        let params = {};
        try { params = fn.arguments ? JSON.parse(fn.arguments) : {}; } catch (e) { params = {}; }
        const result = await executeTool(fn.name, params, ctx);
        toolResults.push({ tool: fn.name, result });
        messages.push({ role: 'tool', tool_call_id: call.id, name: fn.name, content: JSON.stringify(result) });
      }
      continue;
    }

    reply = (message.content || '').trim() || null;
    break;
  }

  // The round cap was reached without the agent settling on an answer.
  if (!reply) {
    await storeCapture({ direction: 'outbound', sequence: nextSequence + 1, raw_text: fallback, conversation_id: conversation ? conversation.id : null });
    return [{ json: { chat_id, message_thread_id, text: fallback } }];
  }

  // --- what the exchange did to the books, recorded as its state ----
  // A transaction settles the exchange; a question continues it. The
  // agent decides what to say, this decides what that means for the
  // conversation it belongs to (ADR 0038) -- bookkeeping, not judgement.
  // An export is delivered as a file beside the reply that describes it.
  const exported = toolResults.find((t) => t.tool === 'export_period' && t.result && t.result.csv);
  if (exported) {
    const botToken = $env.TELEGRAM_DELIVERY_MODE === 'polling' ? $env.TELEGRAM_LOCAL_BOT_TOKEN : $env.TELEGRAM_BOT_TOKEN;
    if (botToken) await telegramSendDocument(botToken, chat_id, exported.result.filename, exported.result.csv);
  }

  const recorded = toolResults.find((t) => t.tool === 'record_transaction' && t.result && t.result.transaction_id);
  // What continues the exchange is the agent still wanting an answer,
  // not what it happened to write on the way. A capture that resolves
  // ends with a confirmation and closes; an opening balance during
  // setup records a transaction and still asks for the next account.
  const stillAsking = /\?\s*$/.test(reply);

  if (recorded && inboundId) {
    await httpJson('PATCH', `${PG}/capture?id=eq.${inboundId}`, Object.assign({ Prefer: 'return=minimal' }, readAuth), {
      state: 'resolved', transaction_id: recorded.result.transaction_id,
    });
  }

  if (stillAsking) {
    if (!conversation) {
      const created = await httpJson('POST', `${PG}/conversation`, Object.assign({ Prefer: 'return=representation' }, readAuth), {
        member_id, kind: 'clarification', step: 'awaiting_answer', payload: {},
      });
      conversation = (created.body || [])[0] || null;
      if (conversation && inboundId) {
        await httpJson('PATCH', `${PG}/capture?id=eq.${inboundId}`, Object.assign({ Prefer: 'return=minimal' }, readAuth), { conversation_id: conversation.id });
      }
    }
    // A41: the same question, with nothing new to go on, is not asked
    // again -- so it is not recorded again either.
    if (!questionsAsked.includes(reply)) {
      await storeCapture({
        direction: 'outbound', sequence: nextSequence + 1, raw_text: reply,
        conversation_id: conversation ? conversation.id : null,
      });
    }
    if (conversation) {
      await httpJson('PATCH', `${PG}/conversation?id=eq.${conversation.id}`, Object.assign({ Prefer: 'return=minimal' }, readAuth), { last_touched_at: new Date().toISOString() });
    }
  } else {
    if (conversation) {
      await httpJson('PATCH', `${PG}/conversation?id=eq.${conversation.id}`, Object.assign({ Prefer: 'return=minimal' }, readAuth), { closed_at: new Date().toISOString() });
    }
    // The closing reply belongs to the capture, not to the exchange
    // that reached it: attaching it would make "every message in the
    // exchange" mean something different from what R6a promises.
    await storeCapture({ direction: 'outbound', sequence: nextSequence + 1, raw_text: reply });
  }

  return [{ json: { chat_id, message_thread_id, text: reply, tool_results: toolResults, prompt_version: PROMPT_VERSION } }];
}

return main();
